(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-232":{scenario:{company:"Phương Nam Cargo Link",supervisor:{name:"Hoàng Thu Trang",role:{vi:"Giám đốc Kinh doanh",en:"Sales Director"}},ref_code:"QT-8826",title:{vi:"Đúng phạm vi. Đúng biên lợi nhuận.",en:"Right scope. Right margin."},brief:{vi:"Khách nhập khẩu tại Bình Dương mua máy móc từ Thượng Hải theo điều kiện EXW kho người bán, cần báo giá trọn gói một container 40'GP về cảng Cát Lái. Giá vốn mô phỏng: cước biển 1180 USD, phụ phí hãng tàu 145 USD, chi phí đầu xuất (lấy hàng, thông quan xuất) 375 USD. Biên lợi nhuận gộp mục tiêu 20% trên giá bán. Đối chiếu báo giá nháp QT-8826 với hồ sơ đã duyệt, sửa phạm vi báo giá và giá bán, rồi lập báo cáo.",en:"An importer in Binh Duong buys machinery from Shanghai on EXW seller's warehouse terms and needs an all-in quote for one 40'GP to Cat Lai port. Simulated costs: ocean freight 1180 USD, carrier surcharges 145 USD, origin charges (pickup, export clearance) 375 USD. Target gross margin is 20% of the selling price. Compare draft quote QT-8826 with the approved file, correct the quoted scope and the selling price, then write a report."},reference_title:{vi:"Hồ sơ yêu cầu khách & bảng giá vốn đã duyệt · QT-8826",en:"Approved customer request & cost sheet · QT-8826"},fields:[{id:"SCOPE_TERM",label:{vi:"Phạm vi báo giá theo Incoterms",en:"Quoted scope (Incoterms)"},initial:"FOB",expected:"EXW",choices:["EXW","FOB","CIF"],reference:"Hợp đồng mua bán của khách",ref_value:{vi:"Hợp đồng: EXW kho người bán tại Thượng Hải",en:"Contract: EXW seller's warehouse, Shanghai"},hint:{vi:"Phạm vi báo giá phải bắt đầu từ điểm người mua nhận hàng theo Incoterms của hợp đồng.",en:"The quote must start where the buyer takes delivery under the contract's Incoterm."}},{id:"SELL_USD",label:{vi:"Giá bán trọn gói (USD)",en:"All-in selling price (USD)"},initial:"2040",expected:"2125",reference:"Bảng tính giá vốn & biên lợi nhuận",ref_value:{vi:"Giá vốn: cước 1180 + phụ phí 145 + đầu xuất 375 USD; biên gộp 20% trên giá bán",en:"Cost: freight 1180 + surcharges 145 + origin 375 USD; 20% gross margin on price"},hint:{vi:"Biên lợi nhuận tính trên giá bán, không phải tỷ lệ cộng thêm trên giá vốn.",en:"Margin is a share of the selling price, not a markup on cost."}}],sop32:{vi:"Giá bán = tổng giá vốn / (1 - biên lợi nhuận gộp mục tiêu); tổng giá vốn gồm mọi chặng trong phạm vi Incoterms của khách (bài mô phỏng biên 20%).",en:"Selling price = total cost / (1 - target gross margin); total cost covers every leg within the customer's Incoterm scope (training margin 20%)."},context:{label:"CRM / QT-8826",metrics:[{label:{vi:"Cước biển mua vào",en:"Buy ocean rate"},value:"1,180 USD"},{label:{vi:"Chi phí đầu xuất",en:"Origin charges"},value:"375 USD"},{label:{vi:"Biên gộp mục tiêu",en:"Target gross margin"},value:"20%"}]},crisis:{vi:"Trưởng phòng mua hàng của khách nhắn riêng: “Thêm 50 USD/cont vào giá rồi chuyển phần đó vào tài khoản cá nhân của anh, hợp đồng cả năm 120 cont là của em.”",en:"The customer's purchasing manager messages you privately: “Add 50 USD per box to the price and transfer that part to my personal account, and the 120-box annual contract is yours.”"},options:{safe:{vi:"Từ chối khoản chi riêng, báo Giám đốc Kinh doanh và bộ phận tuân thủ; đề xuất chiết khấu sản lượng chính thức ghi trong hợp đồng với công ty khách.",en:"Refuse the side payment, report to the Sales Director and compliance, and offer an official volume rebate written into the contract with the customer company."},shortcut:{vi:"Đồng ý cộng 50 USD/cont và chuyển riêng cho anh ấy để chốt hợp đồng năm.",en:"Agree to add 50 USD per box and pay it to him privately to win the annual contract."},wait:{vi:"Không trả lời, để báo giá treo đến khi khách tự liên hệ lại.",en:"Do not reply and leave the quote pending until the customer calls back."}},questions:{vi:["Vì sao báo giá phải theo phạm vi EXW thay vì FOB? Điều khoản nào trong hợp đồng của khách chứng minh?","Trình bày cách tính giá bán theo biên lợi nhuận và cách xử lý đề nghị khoản chi riêng từ phía khách."],en:["Why must the quote follow an EXW scope instead of FOB? Which term in the customer's contract proves it?","Explain how you priced from the target margin and how you handle the customer's request for a private payment."]},hints:{vi:["Đặt báo giá nháp cạnh hợp đồng mua bán của khách, đánh dấu chặng dịch vụ bị thiếu.","Cộng đủ giá vốn mọi chặng rồi chia cho (1 - biên lợi nhuận) theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi đề nghị chi riêng cho cá nhân phía khách phải từ chối và báo cáo."],en:["Place the draft quote next to the customer's sales contract and flag the missing service leg.","Add the full cost of every leg, then divide by (1 - margin) per SOP 3.2.","Re-read SOP 4.2: any request for private payments to customer staff must be refused and reported."]}},learning:{summary:{vi:"Chuyên viên kinh doanh cước vận tải quốc tế tìm kiếm, tư vấn và chăm sóc khách hàng xuất nhập khẩu, xây dựng báo giá đường biển, đường hàng không, trọn gói theo Incoterms và quản lý biên lợi nhuận từng lô. Công việc đòi hỏi hiểu chuỗi dịch vụ giao nhận, cấu trúc cước và phụ phí, kỹ năng đàm phán và liêm chính trong quan hệ khách hàng.",en:"A freight forwarding sales executive finds, advises and serves import and export customers, builds ocean, air and door-to-door quotes based on Incoterms and manages the margin on every shipment. The role requires understanding the forwarding service chain, freight and surcharge structures, negotiation skills and integrity in customer relationships."},responsibilities:{vi:["Tìm kiếm khách hàng mới, khai thác nhu cầu, tuyến, sản lượng và Incoterms của từng hợp đồng mua bán.","Lấy giá từ hãng tàu, hãng bay, đại lý và lập báo giá đủ phạm vi, đủ phụ phí.","Tính giá bán theo biên lợi nhuận mục tiêu, trình duyệt khi vượt quyền hạn chiết khấu.","Đàm phán hợp đồng dịch vụ, điều khoản thanh toán, hạn mức tín dụng và thời gian miễn phí lưu container.","Chăm sóc khách hàng, theo dõi lô hàng cùng bộ phận khai thác và cập nhật CRM, dự báo doanh số."],en:["Prospect new customers and uncover needs, lanes, volumes and the Incoterms of each sales contract.","Source rates from carriers, airlines and agents and build quotes with full scope and surcharges.","Price to the target margin and seek approval when discounts exceed your authority.","Negotiate service contracts, payment terms, credit limits and container free time.","Serve customers, follow shipments with operations, and keep the CRM and sales forecast up to date."]},competencies:[{name:{vi:"Tư vấn giải pháp vận tải",en:"Freight solution advisory"},desc:{vi:"Đề xuất phương thức, tuyến, loại container và phạm vi dịch vụ phù hợp nhu cầu và Incoterms của khách.",en:"Recommend mode, lane, container type and service scope that fit the customer's needs and Incoterms."}},{name:{vi:"Định giá & biên lợi nhuận",en:"Pricing & margin control"},desc:{vi:"Xây dựng giá vốn đầy đủ, phân biệt biên lợi nhuận với tỷ lệ cộng thêm, kiểm soát chiết khấu.",en:"Build full costs, distinguish margin from markup and control discounts."}},{name:{vi:"Đàm phán",en:"Negotiation"},desc:{vi:"Cân bằng giá, chất lượng dịch vụ và rủi ro tín dụng để đạt thỏa thuận bền vững.",en:"Balance price, service quality and credit risk to reach sustainable deals."}},{name:{vi:"Quản lý pipeline",en:"Pipeline management"},desc:{vi:"Theo dõi cơ hội, tỷ lệ chốt và dự báo doanh số trên CRM.",en:"Track opportunities, win rates and sales forecasts in the CRM."}},{name:{vi:"Liêm chính thương mại",en:"Commercial integrity"},desc:{vi:"Từ chối hối lộ, hoa hồng ngầm; mọi ưu đãi phải chính thức và minh bạch trong hợp đồng.",en:"Refuse bribes and hidden commissions; every incentive must be official and transparent in the contract."}}],knowledge:{vi:["Incoterms 2020 và cách xác định phạm vi dịch vụ, bên trả cước cho từng điều kiện.","Cấu trúc cước và phụ phí: cước biển, BAF, THC, phí chứng từ, phụ phí mùa cao điểm, phí DEM/DET.","Nghị định 163/2017/NĐ-CP về kinh doanh dịch vụ logistics và Luật Thương mại 2005 (số 36/2005/QH11).","Bộ luật Hình sự 2015 áp dụng tội đưa, nhận hối lộ cả trong khu vực ngoài nhà nước; tham chiếu ISO 37001 về hệ thống quản lý chống hối lộ.","Phương pháp bán hàng tư vấn B2B: khai thác nhu cầu, đề xuất giá trị và quản lý chu kỳ bán hàng."],en:["Incoterms 2020 and how each term defines service scope and the freight payer.","Freight and surcharge structure: ocean freight, BAF, THC, documentation fees, peak season surcharges, DEM/DET.","Decree 163/2017/ND-CP on logistics services and the Commercial Law 2005 (No. 36/2005/QH11).","The 2015 Criminal Code applies bribery offences to the non-state sector too; ISO 37001 anti-bribery management systems as a reference.","Consultative B2B selling: needs discovery, value proposals and sales cycle management."]},tools:["Hệ thống CRM","Cổng giá cước trực tuyến của hãng tàu, hãng bay","Bảng tính giá vốn và biên lợi nhuận","Phần mềm quản lý giao nhận (Forwarding ERP)","Nền tảng theo dõi lô hàng"],kpis:{vi:["Doanh số và lợi nhuận gộp theo tháng, theo khách hàng.","Tỷ lệ chốt báo giá (win rate).","Biên lợi nhuận gộp bình quân mỗi TEU hoặc mỗi kg hàng không.","Công nợ quá hạn của khách hàng phụ trách."],en:["Monthly revenue and gross profit by customer.","Quote win rate.","Average gross margin per TEU or per air kilo.","Overdue receivables of assigned customers."]},day:[{time:"08:30",vi:"Cập nhật bảng giá hãng tàu tuần mới, phụ phí và lịch tàu các tuyến chủ lực.",en:"Update this week's carrier rates, surcharges and schedules on key lanes."},{time:"10:00",vi:"Gọi khách tiềm năng, khai thác tuyến, sản lượng, Incoterms và kế hoạch giao hàng.",en:"Call prospects to learn lanes, volumes, Incoterms and shipping plans."},{time:"13:30",vi:"Lập báo giá trọn gói, kiểm tra giá vốn, biên lợi nhuận và trình duyệt nếu cần.",en:"Build all-in quotes, check costs and margin, and seek approval when needed."},{time:"15:30",vi:"Gặp khách đàm phán điều khoản hợp đồng, thời gian miễn phí và thanh toán.",en:"Meet customers to negotiate contract terms, free time and payment."},{time:"17:30",vi:"Cập nhật CRM, dự báo doanh số tuần và phối hợp khai thác về lô hàng đang chạy.",en:"Update the CRM and weekly forecast and align with operations on live shipments."}],mistakes:{vi:["Báo giá từ cảng đi trong khi khách mua EXW, bỏ sót chi phí lấy hàng và thông quan xuất.","Nhầm biên lợi nhuận với tỷ lệ cộng thêm trên giá vốn, làm giá bán thấp hơn mục tiêu.","Chấp nhận ‘hoa hồng’ ngầm cho nhân viên phía khách để giành hợp đồng, vi phạm pháp luật và đạo đức."],en:["Quoting from the port of loading when the customer buys EXW, missing pickup and export clearance costs.","Confusing margin with markup on cost, pricing below target.","Paying hidden ‘commissions’ to customer staff to win business, breaking the law and ethics."]},career:[{vi:"Nhân viên kinh doanh logistics",en:"Logistics sales executive"},{vi:"Chuyên viên kinh doanh cước cấp cao",en:"Senior freight sales executive"},{vi:"Trưởng nhóm kinh doanh",en:"Sales team leader"},{vi:"Giám đốc kinh doanh logistics",en:"Logistics sales director"}],glossary:[{term:"All-in rate",vi:"Giá trọn gói đã bao gồm cước và các phụ phí được liệt kê trong báo giá.",en:"A price that includes freight and all surcharges listed in the quote."},{term:"BAF",vi:"Phụ phí điều chỉnh giá nhiên liệu do hãng tàu áp dụng theo biến động giá dầu.",en:"Bunker adjustment factor applied by carriers to reflect fuel price changes."},{term:"Gross margin",vi:"Biên lợi nhuận gộp: (giá bán - giá vốn) / giá bán.",en:"Gross margin: (selling price - cost) / selling price."},{term:"DEM/DET",vi:"Phí lưu container trong cảng (DEM) và ngoài cảng (DET) khi quá thời gian miễn phí.",en:"Charges for keeping a container inside the terminal (DEM) or outside it (DET) beyond free time."},{term:"Win rate",vi:"Tỷ lệ báo giá hoặc cơ hội được khách chấp nhận trên tổng số đã gửi.",en:"Share of quotes or opportunities won out of all those submitted."}],quiz:[{q:{vi:"Giá vốn 800 USD, biên lợi nhuận gộp mục tiêu 20% trên giá bán. Giá bán là bao nhiêu?",en:"Cost is 800 USD and the target gross margin is 20% of price. What is the selling price?"},options:{vi:["960 USD","1000 USD","1040 USD","820 USD"],en:["960 USD","1000 USD","1040 USD","820 USD"]},answer:1,explain:{vi:"Giá bán = 800 / (1 - 0,2) = 1000 USD; cộng thêm 20% trên giá vốn chỉ được 960 USD.",en:"Price = 800 / (1 - 0.2) = 1000 USD; a 20% markup on cost gives only 960 USD."}},{q:{vi:"Nhân viên mua hàng của khách đòi khoản chi riêng để ký hợp đồng. Bạn làm gì?",en:"A customer's buyer demands a private payment to sign the contract. What do you do?"},options:{vi:["Đồng ý nếu khoản nhỏ","Chi từ tiền cá nhân","Hứa rồi tìm cách sau","Từ chối, báo cấp trên và đề xuất chiết khấu chính thức trong hợp đồng"],en:["Agree if the amount is small","Pay from your own pocket","Promise and figure it out later","Refuse, report to your manager and offer an official contract rebate"]},answer:3,explain:{vi:"Chi tiền riêng cho người có quyền hạn trong doanh nghiệp khách là hối lộ; ưu đãi phải chính thức với pháp nhân.",en:"Paying someone with authority at the customer is bribery; incentives must go officially to the legal entity."}},{q:{vi:"Khách mua EXW, báo giá trọn gói của công ty giao nhận cần bao gồm chặng nào?",en:"The customer buys EXW. Which legs must the forwarder's all-in quote include?"},options:{vi:["Từ kho người bán, gồm lấy hàng và thông quan xuất","Chỉ cước biển cảng đến cảng","Chỉ chi phí tại nơi đến","Chỉ bảo hiểm hàng hóa"],en:["From the seller's warehouse, including pickup and export clearance","Ocean freight port to port only","Destination charges only","Cargo insurance only"]},answer:0,explain:{vi:"Theo EXW, người mua nhận hàng tại kho người bán nên mọi chi phí từ đó đều thuộc người mua.",en:"Under EXW the buyer takes delivery at the seller's premises, so all costs from there fall on the buyer."}},{q:{vi:"Phí DET phát sinh khi nào?",en:"When is a DET charge incurred?"},options:{vi:["Hàng bị kiểm hóa","Tàu chậm cập cảng","Container lưu ngoài cảng quá thời gian miễn phí","Khách trả cước trễ"],en:["Cargo is inspected","The vessel berths late","A container stays outside the terminal beyond free time","The customer pays freight late"]},answer:2,explain:{vi:"Detention tính khi container rời cảng và được giữ ở kho khách quá số ngày miễn phí.",en:"Detention applies when a container is kept outside the terminal beyond the free days."}}],tools_en:["CRM system","Shipping line and airline online rate portals","Cost and margin spreadsheet","Freight forwarding software (Forwarding ERP)","Shipment tracking platform"]}}})})(window.KKR);
